/**
 * MODULE 07 — Vulnerability & CVE Intelligence.
 *   #/vulnerabilities         snapshot table with prioritisation, filters, freshness and export
 *   #/vulnerabilities/:cve    CVE page: NVD description, CVSS breakdown, KEV action, EPSS, references
 *
 * Data: data/cve-snapshot.json, generated by tools/update-cve-snapshot.ps1 from
 * CISA KEV, NIST NVD (CVE API 2.0) and FIRST EPSS. Nothing here is typed by hand.
 */
import { el, formatNumber, provenanceBadge, severityBadge } from '../utils/dom.js';
import { load } from '../data-service.js';
import { createFilterBar, applyFilters } from '../components/filter-bar.js';
import { createDataTable } from '../components/data-table.js';
import { toast } from '../components/toast.js';
import { exportCSV, stamp } from '../components/export.js';
import { formatSourceDate } from '../components/intel-ui.js';
import { parseCvssVector, prioritise, TIER_LABEL, daysBetween } from '../network/cvss.js';

const STALE_DAYS = 7;
const sevKey = (s) => String(s || '').toLowerCase();
const fmtDate = (d) => (d ? formatSourceDate(String(d).slice(0, 10)) : '—');

/** Find Sentinel X profiles and dossiers that mention a CVE. */
async function relatedContent(cveID) {
  const out = [];
  try {
    const [{ data: intel }, { data: lib }] = await Promise.all([load('intel'), load('attacks')]);
    intel.profiles.forEach((p) => { if (JSON.stringify(p).includes(cveID)) out.push({ label: `Threat profile: ${p.name}`, href: `#/threat-intel/${p.id}` }); });
    lib.attacks.forEach((a) => { if (JSON.stringify(a).includes(cveID)) out.push({ label: `Attack dossier: ${a.name}`, href: `#/attacks/${a.id}` }); });
  } catch { /* optional */ }
  return out;
}

function freshnessNotice(data) {
  const age = daysBetween(data.generatedAt, new Date());
  const stale = age > STALE_DAYS;
  const s = data.sources;
  return el('div', { class: `notice ${stale ? 'is-error' : ''}`, role: stale ? 'alert' : null },
    el('span', { 'aria-hidden': 'true' }, stale ? '⚠' : 'ⓘ'),
    el('span', null,
      el('strong', null, stale ? `Snapshot is ${age} days old. ` : `Snapshot fetched ${fmtDate(data.generatedAt)}${age === 0 ? ' (today)' : ` (${age} day${age === 1 ? '' : 's'} ago)`}. `),
      `KEV catalog version ${s.kev.catalogVersion}, released ${fmtDate(s.kev.dateReleased)} (${formatNumber(s.kev.totalEntries)} entries in total). `,
      `NVD records fetched ${fmtDate(s.nvd.fetchedAt)}. EPSS scores dated ${fmtDate(s.epss.scoreDate)}. `,
      data.note));
}

const tierPill = (t) => el('span', { class: `prio prio-${t}`, title: TIER_LABEL[t] }, `${t} · ${TIER_LABEL[t]}`);

export async function renderVulnerabilities(view) {
  const { data } = await load('cves');
  const today = new Date();
  const rows = data.cves.map((c) => {
    const pr = prioritise(c);
    const cv = c.nvd && c.nvd.cvss;
    return {
      ...c, id: c.cveID, tier: pr.tier, reasons: pr.reasons,
      score: cv ? Number(cv.baseScore) : null, severity: cv ? sevKey(cv.baseSeverity) : 'info',
      epssScore: c.epss ? c.epss.score : null, ransomware: c.knownRansomwareCampaignUse === 'Known' ? 'known' : 'unknown',
      vendor: c.vendorProject, pastDue: daysBetween(c.dueDate, today) > 0,
      _search: [c.cveID, c.vendorProject, c.product, c.vulnerabilityName, ...(c.nvd ? c.nvd.cwes : [])].join(' ')
    };
  });

  const count = el('span', { class: 'kpi-sub', role: 'status', 'aria-live': 'polite' });
  const table = createDataTable({
    caption: 'CVE snapshot', pageSize: 15, rows, initialSort: { key: 'tier', dir: 'asc' },
    onRowActivate: (r) => { location.hash = `#/vulnerabilities/${r.cveID}`; }, rowLabel: (r) => r.cveID,
    columns: [
      { key: 'cveID', label: 'CVE', sortable: true, className: 'mono', render: (r) => el('a', { href: `#/vulnerabilities/${r.cveID}` }, r.cveID) },
      { key: 'vendor', label: 'Vendor / product', sortable: true, render: (r) => `${r.vendorProject} ${r.product}` },
      { key: 'tier', label: 'Priority', sortable: true, render: (r) => tierPill(r.tier) },
      { key: 'score', label: 'CVSS', sortable: true, defaultDir: 'desc', render: (r) => (r.score === null ? '—' : el('span', null, severityBadge(r.severity), ` ${r.score.toFixed(1)}`)) },
      { key: 'epssScore', label: 'EPSS', sortable: true, defaultDir: 'desc', className: 'mono', render: (r) => (r.epssScore === null ? '—' : `${(r.epssScore * 100).toFixed(1)}%`) },
      { key: 'ransomware', label: 'Ransomware', sortable: true, render: (r) => (r.ransomware === 'known' ? el('span', { class: 'sev-critical' }, 'Known') : el('span', { class: 'kpi-sub' }, 'Unknown')) },
      { key: 'dateAdded', label: 'KEV added', sortable: true, defaultDir: 'desc', className: 'mono' }
    ]
  });
  const vendors = [...new Set(rows.map((r) => r.vendor))].sort((a, b) => a.localeCompare(b));
  let state;
  const fb = createFilterBar({
    ariaLabel: 'Filter CVEs', searchLabel: 'Search', searchPlaceholder: 'CVE ID, vendor, product, CWE…',
    chips: [
      { key: 'severity', label: 'CVSS severity', options: ['critical', 'high', 'medium', 'low'].map((s) => ({ value: s, label: s, className: `sev-${s}` })) },
      { key: 'tier', label: 'Priority', options: ['P1', 'P2', 'P3', 'P4'].map((t) => ({ value: t, label: `${t} ${TIER_LABEL[t]}` })) }
    ],
    selects: [
      { key: 'ransomware', label: 'Ransomware use', options: [{ value: 'known', label: 'Known' }, { value: 'unknown', label: 'Unknown' }] },
      { key: 'vendor', label: 'Vendor', options: vendors.map((v) => ({ value: v, label: v })) }
    ],
    onChange: (s) => { state = s; const out = applyFilters(rows, s, { searchFields: ['_search'] }); table.setRows(out); count.textContent = `${out.length} of ${rows.length} CVEs`; }
  });
  state = fb.getState(); count.textContent = `${rows.length} of ${rows.length} CVEs`;

  const exportBtn = el('button', { class: 'btn btn-sm', type: 'button' }, 'Export CSV');
  exportBtn.addEventListener('click', () => {
    const out = table.getSortedRows();
    if (!out.length) return toast('Nothing to export.', { variant: 'warning' });
    exportCSV(`sentinel-x-cve-snapshot-${stamp()}.csv`, out, [
      { key: 'cveID', label: 'CVE' }, { key: 'vendorProject', label: 'Vendor' }, { key: 'product', label: 'Product' },
      { key: 'tier', label: 'Priority' }, { key: 'score', label: 'CVSS base score' }, { key: 'severity', label: 'CVSS severity' },
      { key: 'epssScore', label: 'EPSS' }, { key: 'knownRansomwareCampaignUse', label: 'Known ransomware use' },
      { key: 'dateAdded', label: 'KEV date added' }, { key: 'dueDate', label: 'KEV due date (BOD 22-01)' },
      { key: 'snapshot', label: 'Snapshot generated', value: () => data.generatedAt }
    ]);
    toast(`Exported ${out.length} CVEs`, { variant: 'success' });
  });

  const kpi = (label, value, sub, cls = '') => el('div', { class: `card kpi ${cls}` }, el('span', { class: 'kpi-label' }, label), el('span', { class: 'kpi-value' }, String(value)), el('span', { class: 'kpi-sub' }, sub));
  view.classList.add('stack');
  view.append(
    el('header', { class: 'page-head soc-head' },
      el('div', null,
        el('span', { class: 'eyebrow' }, 'Module 07'),
        el('h1', null, 'Vulnerability & CVE Intelligence'),
        el('p', { class: 'lede' }, `${rows.length} actively exploited vulnerabilities from the CISA KEV catalog: CVEs referenced elsewhere in Sentinel X plus the newest KEV additions, enriched with NVD CVSS data and FIRST EPSS scores.`),
        el('div', { class: 'meta-row' }, provenanceBadge('documented'), el('span', { class: 'kpi-sub' }, 'Generated by tools/update-cve-snapshot.ps1'))),
      el('div', { class: 'btn-row' }, exportBtn)),
    freshnessNotice(data),
    el('div', { class: 'grid grid-4' },
      kpi('CVEs in snapshot', rows.length, `of ${formatNumber(data.sources.kev.totalEntries)} in KEV`, 'status-live'),
      kpi('P1 · Act now', rows.filter((r) => r.tier === 'P1').length, 'KEV + ransomware or CVSS ≥ 9', 'sev-critical'),
      kpi('Known ransomware use', rows.filter((r) => r.ransomware === 'known').length, 'Per CISA KEV', 'sev-high'),
      kpi('CVSS critical', rows.filter((r) => r.severity === 'critical').length, 'NVD base score ≥ 9.0', 'sev-medium')),
    el('section', { class: 'card', 'aria-labelledby': 'cve-h' },
      el('div', { class: 'section-head' }, el('h2', { id: 'cve-h' }, 'CVE snapshot'), count),
      fb.element, table.element),
    el('section', { class: 'card', 'aria-labelledby': 'prio-h' },
      el('h2', { id: 'prio-h' }, 'How priority is calculated'),
      el('p', null, 'A transparent teaching model, not an industry standard. Your own asset exposure and business impact should adjust it. CISA\'s Stakeholder-Specific Vulnerability Categorization (SSVC) is a structured way to do that.'),
      el('table', { class: 'kbd-table' }, el('caption', { class: 'visually-hidden' }, 'Priority tiers and rules'),
        el('thead', null, el('tr', null, el('th', { scope: 'col' }, 'Tier'), el('th', { scope: 'col' }, 'Rule'))),
        el('tbody', null,
          el('tr', null, el('td', null, tierPill('P1')), el('td', null, 'Listed in KEV and (known ransomware use or CVSS ≥ 9.0)')),
          el('tr', null, el('td', null, tierPill('P2')), el('td', null, 'Listed in KEV')),
          el('tr', null, el('td', null, tierPill('P3')), el('td', null, 'EPSS ≥ 10% or CVSS ≥ 9.0')),
          el('tr', null, el('td', null, tierPill('P4')), el('td', null, 'Everything else')))),
      el('p', { class: 'kpi-sub' }, 'CVSS measures severity, EPSS estimates the probability of exploitation activity in the next 30 days, and KEV confirms exploitation has already happened. They answer different questions, which is why the model combines them.'),
      el('div', { class: 'btn-row' },
        el('a', { class: 'btn btn-sm', href: data.sources.kev.url, target: '_blank' }, 'CISA KEV ↗'),
        el('a', { class: 'btn btn-sm', href: data.sources.nvd.url, target: '_blank' }, 'NIST NVD ↗'),
        el('a', { class: 'btn btn-sm', href: data.sources.epss.url, target: '_blank' }, 'FIRST EPSS ↗'),
        el('a', { class: 'btn btn-sm', href: 'https://www.cisa.gov/stakeholder-specific-vulnerability-categorization-ssvc', target: '_blank' }, 'CISA SSVC ↗')))
  );
  return () => view.classList.remove('stack');
}

export async function renderVulnerability(view, { params }) {
  const { data } = await load('cves');
  const c = data.cves.find((x) => x.cveID === String(params.id).toUpperCase());
  if (!c) {
    view.append(el('header', { class: 'page-head' }, el('span', { class: 'eyebrow' }, 'Module 07'), el('h1', null, 'CVE not in snapshot'),
      el('p', { class: 'lede' }, `“${params.id}” is not in the current snapshot. Check the live sources: `, el('a', { href: `https://nvd.nist.gov/vuln/detail/${encodeURIComponent(String(params.id).toUpperCase())}`, target: '_blank' }, 'NVD ↗'))),
      el('a', { class: 'btn btn-primary', href: '#/vulnerabilities' }, '← CVE snapshot'));
    return;
  }
  document.title = `${c.cveID} · Vulnerability Intelligence · Joachim's Sentinel X`;
  const n = c.nvd || {};
  const cv = n.cvss;
  const parsed = cv ? parseCvssVector(cv.vector) : null;
  const pr = prioritise(c);
  const related = await relatedContent(c.cveID);
  const due = daysBetween(c.dueDate, new Date());

  view.classList.add('stack');
  view.append(
    el('nav', { class: 'crumbs', 'aria-label': 'Breadcrumb' }, el('a', { href: '#/vulnerabilities' }, 'Vulnerability Intelligence'), ' / ', el('span', { 'aria-current': 'page' }, c.cveID)),
    el('header', { class: 'page-head' },
      el('span', { class: 'eyebrow' }, `${c.vendorProject} · ${c.product}`),
      el('h1', null, `${c.cveID}: ${c.vulnerabilityName}`),
      el('div', { class: 'meta-row' }, tierPill(pr.tier), cv ? severityBadge(sevKey(cv.baseSeverity)) : null, provenanceBadge('documented'),
        el('span', { class: 'kpi-sub' }, `Snapshot ${fmtDate(data.generatedAt)}`))),
    el('div', { class: 'grid grid-4' },
      el('div', { class: `card kpi sev-${cv ? sevKey(cv.baseSeverity) : 'info'}` }, el('span', { class: 'kpi-label' }, `CVSS ${cv ? cv.version : ''}`), el('span', { class: 'kpi-value' }, cv ? Number(cv.baseScore).toFixed(1) : '—'), el('span', { class: 'kpi-sub' }, cv ? `${cv.baseSeverity} · source ${cv.source}` : 'No CVSS data in NVD')),
      el('div', { class: 'card kpi sev-high' }, el('span', { class: 'kpi-label' }, 'EPSS'), el('span', { class: 'kpi-value' }, c.epss ? `${(c.epss.score * 100).toFixed(1)}%` : '—'), el('span', { class: 'kpi-sub' }, c.epss ? `Percentile ${(c.epss.percentile * 100).toFixed(1)} · ${fmtDate(c.epss.date)}` : 'Not available')),
      el('div', { class: 'card kpi sev-critical' }, el('span', { class: 'kpi-label' }, 'KEV added'), el('span', { class: 'kpi-value kpi-date' }, fmtDate(c.dateAdded)), el('span', { class: 'kpi-sub' }, `Ransomware use: ${c.knownRansomwareCampaignUse}`)),
      el('div', { class: 'card kpi sev-medium' }, el('span', { class: 'kpi-label' }, 'Federal due date'), el('span', { class: 'kpi-value kpi-date' }, fmtDate(c.dueDate)), el('span', { class: 'kpi-sub' }, due > 0 ? `${due} days ago (BOD 22-01)` : `In ${-due} days (BOD 22-01)`))),
    el('section', { class: 'card', 'aria-labelledby': 'desc-h' },
      el('h2', { id: 'desc-h' }, 'Description'),
      el('p', null, n.description || c.shortDescription),
      el('dl', { class: 'dl' },
        el('dt', null, 'NVD published'), el('dd', null, fmtDate(n.published)),
        el('dt', null, 'NVD last modified'), el('dd', null, fmtDate(n.lastModified)),
        el('dt', null, 'NVD status'), el('dd', null, n.status || '—'),
        el('dt', null, 'Weakness (CWE)'), el('dd', null, (n.cwes && n.cwes.length ? n.cwes : c.kevCwes || []).map((w, k) => [k ? ', ' : '', el('a', { href: `https://cwe.mitre.org/data/definitions/${w.replace('CWE-', '')}.html`, target: '_blank' }, w)])) )),
    el('div', { class: 'grid grid-2' },
      el('section', { class: 'card', 'aria-labelledby': 'kev-h' },
        el('h2', { id: 'kev-h' }, 'CISA KEV entry'),
        el('p', null, c.shortDescription),
        el('h3', { class: 'chart-title' }, 'Required action'),
        el('p', null, c.requiredAction),
        c.notes ? [el('h3', { class: 'chart-title' }, 'Notes'), el('p', { class: 'kev-notes' }, c.notes)] : null),
      el('section', { class: 'card', 'aria-labelledby': 'cvss-h' },
        el('h2', { id: 'cvss-h' }, 'CVSS breakdown'),
        cv ? el('p', { class: 'mono kpi-sub' }, cv.vector) : el('p', { class: 'bar-empty' }, 'No CVSS vector available.'),
        parsed ? el('table', { class: 'kbd-table' }, el('caption', { class: 'visually-hidden' }, 'CVSS base metrics'),
          el('thead', null, el('tr', null, el('th', { scope: 'col' }, 'Metric'), el('th', { scope: 'col' }, 'Value'))),
          el('tbody', null, parsed.metrics.map((m) => el('tr', null, el('td', null, `${m.name} (${m.key})`), el('td', null, `${m.label} (${m.value})`))))) : null)),
    el('section', { class: 'card', 'aria-labelledby': 'why-h' },
      el('h2', { id: 'why-h' }, `Priority ${pr.tier}: ${TIER_LABEL[pr.tier]}`),
      el('ul', { class: 'checklist' }, pr.reasons.map((r) => el('li', null, r)))),
    related.length ? el('section', { class: 'card', 'aria-labelledby': 'rel-h' }, el('h2', { id: 'rel-h' }, 'Elsewhere in Sentinel X'),
      el('div', { class: 'btn-row' }, related.map((r) => el('a', { class: 'btn btn-sm', href: r.href }, r.label)))) : null,
    el('section', { class: 'card', 'aria-labelledby': 'refs-h' },
      el('h2', { id: 'refs-h' }, 'References'),
      el('ul', { class: 'source-list ref-list' },
        el('li', null, el('a', { href: `https://nvd.nist.gov/vuln/detail/${c.cveID}`, target: '_blank' }, `NVD: ${c.cveID} ↗`)),
        el('li', null, el('a', { href: data.sources.kev.url, target: '_blank' }, 'CISA Known Exploited Vulnerabilities Catalog ↗')),
        (n.references || []).map((r) => el('li', null, el('a', { href: r.url, target: '_blank' }, r.url), r.tags && r.tags.length ? el('span', { class: 'source-meta' }, r.tags.join(', ')) : null))),
      el('p', { class: 'kpi-sub' }, 'References are copied from the NVD record at snapshot time and were not individually checked.'))
  );
  return () => view.classList.remove('stack');
}
